import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class AppAssets {
  static final Uint8List onboarding1Bytes = base64Decode(_onboarding1B64);
  static final Uint8List onboarding2Bytes = base64Decode(_onboarding2B64);
  static final Uint8List onboarding3Bytes = base64Decode(_onboarding3B64);
  static final Uint8List brandCoverBytes = base64Decode(_brandCoverB64);

  static Uint8List? onboardingBytes(int step) {
    switch (step) {
      case 1:
        return onboarding1Bytes;
      case 2:
        return onboarding2Bytes;
      case 3:
        return onboarding3Bytes;
      default:
        return null;
    }
  }

  static Widget onboardingImage(int step, {BoxFit fit = BoxFit.cover, Widget? fallback}) {
    final bytes = onboardingBytes(step);
    if (bytes != null) {
      return Image.memory(
        bytes,
        fit: fit,
        gaplessPlayback: true,
        errorBuilder: (context, error, stackTrace) => fallback ?? const SizedBox.shrink(),
      );
    }
    return fallback ?? const SizedBox.shrink();
  }

  static Widget brandCoverImage({BoxFit fit = BoxFit.cover, Widget? fallback}) {
    return Image.memory(
      brandCoverBytes,
      fit: fit,
      gaplessPlayback: true,
      errorBuilder: (context, error, stackTrace) => fallback ?? const SizedBox.shrink(),
    );
  }

  static const String _onboarding1B64 = "";
  static const String _onboarding2B64 = "";
  static const String _onboarding3B64 = "";
  static const String _brandCoverB64 = "";
}
